window.AUTH=window.AUTH||{};window.AUTH["16-1436"]={"d":"16-1436","id":"2017/16-1436","n":"Trump v. International Refugee Assistance Project","src":["osg"],"briefs":[{"k":"petitioner","label":"Brief for the petitioners","date":"2017-08-10","url":"https://www.justice.gov/osg/media/908461/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/trump-v-international-refugee-assistance-project-trump-v-state-hawaii","n":134},{"k":"reply","label":"Reply brief for the petitioners","date":"2017-10-04","url":"https://www.justice.gov/osg/media/916131/dl?inline","side":"pet","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/trump-v-international-refugee-assistance-project-trump-v-hawaii","n":105}],"opinion":null,"tr":false,"items":[{"t":"case","label":"Abourezk v. Reagan","cite":"785 F.2d 1043","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/785/1043/","by":{"0":"40, 58","1":"6, 18"}},{"t":"case","label":"Alfred L. Snapp & Son, Inc. v. Puerto Rico ex rel. Barez","cite":"458 U.S. 592","y":1982,"id":"1981/80-1305","sc":1,"sum":"Puerto Rico has parens patriae standing to maintain this suit. Pp. 600-610. ALFRED L. SNAPP & SON, INC. v. PUERTO RICO (a) In order to maintain a parens patriaeaction, a State must articulate an interest apart from the interests of particular private parties, that is, the State must be more than a nominal party. The State must express a \"quasi-sovereign\" interest, such as its interest in the health and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","1":"15"}},{"t":"case","label":"Allen v. Wright","cite":"468 U.S. 737","y":1984,"id":"1983/81-757","sc":1,"sum":"The Court found that the circumstances involved in this case did not warrant federal-court adjudication.","sumSrc":"Oyez","by":{"0":"31","1":"14"}},{"t":"case","label":"Allende v. Shultz","cite":"845 F.2d 1111","y":1988,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/845/1111/","by":{"0":"40, 58"}},{"t":"case","label":"Already, LLC v. Nike, Inc.","cite":"568 U.S. 85","y":2013,"id":"2012/11-982","sc":1,"sum":"The Court held that a covenant not to sue invalidates a company’s counterclaim for trademark enforcement.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Alvarez v. Smith","cite":"558 U.S. 87","y":2009,"id":"2009/08-351","sc":1,"sum":"A case which the Court dismissed regarding property seizure under the Illinois Drug Asset Forfeiture Procedure Act (DAFPA).","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Arizonans for Official English v. Arizona","cite":"520 U.S. 43","y":1997,"id":"1996/95-974","sc":1,"sum":"Announced by Justice Ruth Bader Ginsburg, the Court held that the dispute was moot due to the previous resignation of Yniguez. The Court did not rule on the constitutionality of the article.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Baker v. Carr","cite":"369 U.S. 186","y":1962,"id":"1960/6","sc":1,"sum":"The Court found that redistricting issues present justiciable questions, and in which the Court reframed its political question doctrine.","sumSrc":"Oyez","by":{"0":"75"}},{"t":"case","label":"Block v. Community Nutrition Inst.","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"sum":"The individual consumers may not obtain judicial review of the milk market orders in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26","1":"3, 8"}},{"t":"case","label":"Board of Educ. of Kiryas Joel Village Sch. Dist. v. Grumet","cite":"512 U.S. 687","y":1994,"id":"1993/93-517","sc":1,"sum":"In a 6-to-3 decision, the Court held that the statute's purpose was to exclude all but those who lived in and practiced the village enclave's extreme form of Judaism.","sumSrc":"Oyez","by":{"0":"73"}},{"t":"case","label":"Brownell v. Tom We Shung","cite":"352 U.S. 180","y":1956,"id":"1956/43","sc":1,"sum":"Under § 10 of the Administrative Procedure Act, an alien whose exclusion has been ordered administratively under the Immigration and Nationality Act of 1952, and who neither claims citizenship nor holds a certificate of identity issued under § 360 (b) of that Act, may obtain judicial review of such order by an action in a federal district court for a declaratory judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25","1":"3"}},{"t":"case","label":"Chicago & S. Air Lines, Inc. v. Waterman S.S. Corp.","cite":"333 U.S. 103","y":1948,"id":"scdb/1947-037","sc":1,"by":{"0":"42"}},{"t":"case","label":"Church of the Lukumi Babalu Aye, Inc. v. City of Hialeah","cite":"508 U.S. 520","y":1993,"id":"1992/91-948","sc":1,"sum":"The Court found that an ordinance banning religious animal sacrifice was unconstitutional under the Free Exercise Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"70, 73","1":"12, 34, 35"}},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"sum":"In a 5-to-4 decision, the Court held that federal courts were without jurisdiction to entertain Lyons' claim for injunctive relief.","sumSrc":"Oyez","by":{"0":"79"}},{"t":"case","label":"DaimlerChrysler Corp. v. Cuno","cite":"547 U.S. 332","y":2006,"id":"2005/04-1704","sc":1,"sum":"The Supreme Court did not reach the central question presented, finding instead that Cuno and the other plaintiffs did not have standing to bring the suit. Chief Justice John Roberts, for the unanimous Court, wrote that simply alleging standing based on their status as taxpayers in Ohio and Michigan did not give them a sufficiently strong interest in the case.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Dalton v. Specter","cite":"511 U.S. 462","y":1994,"id":"1993/93-289","sc":1,"sum":"Judicial review is not available for respondents' claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","1":"6"}},{"t":"case","label":"Davis v. FEC","cite":"554 U.S. 724","y":2008,"id":"2007/07-320","sc":1,"sum":"Although all nine Justices agreed that Davis had standing to argue his case before the Court, only a 5-4 majority held that the contribution limits violated the First Amendment. In his majority opinion, Justice Samuel Alito noted that the Court had never upheld the constitutionality of a law imposing different contribution limits for candidates competing against one another.","sumSrc":"Oyez","by":{"0":"36","1":"16"}},{"t":"case","label":"Demore v. Kim","cite":"538 U.S. 510","y":2003,"id":"2002/01-1491","sc":1,"sum":"The Court held, 6-3, that the Immigration and Nationality Act does not deprive the federal courts of jurisdiction to grant habeas relief to aliens challenging their detention under section 1226(c) and, 5-4, that detention during removal proceedings is a constitutionally permissible part of that process.","sumSrc":"Oyez","by":{"0":"64"}},{"t":"case","label":"Department of the Navy v. Egan","cite":"484 U.S. 518","y":1988,"id":"1987/86-1552","sc":1,"sum":"In an appeal pursuant to § 7513, the Board does not have authority to review the substance of an underlying security-clearance determination in the course of reviewing an adverse action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Florida Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"54"}},{"t":"case","label":"Elk Grove Unified Sch. Dist. v. Newdow","cite":"542 U.S. 1","y":2004,"id":"2003/02-1624","sc":1,"sum":"The Court held that a divorced father did not have sufficient custody of his daughter to challenge the Establishment Clause of the First Amendment on her behalf.","sumSrc":"Oyez","by":{"0":"29, 30"}},{"t":"case","label":"Fiallo v. Bell","cite":"430 U.S. 787","y":1977,"id":"1976/75-6297","sc":1,"sum":"Sections 101 (b) (1) (D) and 101 (b) (2) of the Immigration and Nationality Act of 1952, which have the effect of excluding the relationship between an illegitimate child and his natural father (as opposed to his natural mother) from the special preference immigration status accorded by the Act to the \"child\" or \"parent\" of a United States citizen or lawful permanent resident, held not to be unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23, 24, 63, 64","1":"30"}},{"t":"case","label":"Franklin v. Massachusetts","cite":"505 U.S. 788","y":1992,"id":"1991/91-1502","sc":1,"sum":"Evaluating the Secretary's chosen procedure under Article I Section 2 of the Constitution, however, Justice O'Connor ruled that the decision to include overseas personnel of the Department of Defense was a reasonable interpretation of the Constitution's intent. \"The Secretary's judgment does not hamper the underlying constitutional goal of equal representation, but, assuming that employees temporarily stationed abroad have indeed retained their ties to their home states, actually promotes equality,\" wrote Justice O'Connor.","sumSrc":"Oyez","by":{"0":"42","1":"4"}},{"t":"case","label":"Harisiades v. Shaughnessy","cite":"342 U.S. 580","y":1952,"id":"scdb/1951-056","sc":1,"by":{"0":"23","1":"5"}},{"t":"case","label":"Hein v. Freedom From Religion Found., Inc.","cite":"551 U.S. 587","y":2007,"id":"2006/06-157","sc":1,"sum":"By a 5-4 vote, the Court ruled that citizens do not have standing as taxpayers to bring Establishment Clause challenges against Executive Branch programs that are funded by appropriations for general administrative expenses.","sumSrc":"Oyez","by":{"0":"72"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"0":"48, 50"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"0":"66","1":"29, 30"}},{"t":"case","label":"Kerry v. Din","cite":"135 S. Ct. 2128","y":2015,"id":"2014/13-1402","sc":1,"sum":"The Court held that the lack of a detailed explanation for a denial of a visa application does not violate the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"0":"27, 67, 68","1":"2, 31, 32"}},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"sum":"The Court held that the First Amendment did not obligate Kleindienst to grant a waiver to Mandel.","sumSrc":"Oyez","by":{"0":"passim","1":"2, 10, 29, 30"}},{"t":"case","label":"Kowalski v. Tesmer","cite":"543 U.S. 125","y":2004,"id":"2004/03-407","sc":1,"sum":"The Court held that the attorneys lacked third-party standing to sue on behalf of the Michigan indigent defendants. The attorneys did not have close relationships with the indigent defendants, nor was there a hindrance to these defendants' ability to advance their own constitutional rights against the Michigan scheme.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Lemon v. Kurtzman","cite":"403 U.S. 602","y":1971,"id":"1970/89","sc":1,"sum":"The Court found that Pennsylvania and Rhode Island statutes granting salary supplements to teachers at \"church-related educational institutions\" was unconstitutional for violating the Establishment Clause of the First Amendment. The case established the Lemon Test for determining if the government is becoming too involved in religious activities.","sumSrc":"Oyez","by":{"0":"12, 70"}},{"t":"case","label":"Lewis v. Casey","cite":"518 U.S. 343","y":1996,"id":"1995/94-1511","sc":1,"sum":"The Court held that the success of Casey's systemic challenge was dependent on the ability to show widespread actual injury, and the District Court's failure to identify anything more than isolated instances of actual injury rendered its finding of a systemic Bounds violation invalid.","sumSrc":"Oyez","by":{"0":"78, 79, 80"}},{"t":"case","label":"Linda R.S. v. Richard D.","cite":"410 U.S. 614","y":1973,"id":"1972/71-6078","sc":1,"sum":"Although appellant has an interest in her child's support, application of Art. 602 would not result in support but only in the father's incarceration, and a private citizen lacks a judicially cognizable interest in the prosecution or nonprosecution of another. Pp. 616-619. 335 F. Supp. 804, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Lynch v. Donnelly","cite":"465 U.S. 668","y":1984,"id":"1983/82-1256","sc":1,"sum":"The Court held that a nativity scene in the city's shopping district did not violate the Establishment Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"70"}},{"t":"case","label":"Madsen v. Women’s Health Ctr., Inc.","cite":"512 U.S. 753","y":1994,"id":"1993/93-880","sc":1,"sum":"In a majority opinion authored by Chief Justice William H. Rehnquist, the Court found that the state of Florida could only restrict protesters to the extent necessary to allow the clinic to run and the staff to live in their homes without interference.","sumSrc":"Oyez","by":{"0":"79"}},{"t":"case","label":"McCreary County v. ACLU of Ky.","cite":"545 U.S. 844","y":2005,"id":"2004/03-1693","sc":1,"sum":"The Court found the display of the Ten Commandments in public schools and courthouses violated the Establishment Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"22, 70, 71, 72, 73","1":"34"}},{"t":"case","label":"McGowan v. Maryland","cite":"366 U.S. 420","y":1961,"id":"1960/8","sc":1,"sum":"The Court found that the blue laws did not violate the Free Exercise Clause because the employees allege only economic injury and not infringement on their own religious practices. The Court also found that the blue laws did not violate the division between church and state.","sumSrc":"Oyez","by":{"0":"29","1":"11, 12"}},{"t":"case","label":"Nademi v. INS","cite":"679 F.2d 811","y":1982,"url":"https://www.courtlistener.com/c/F.2d/679/811/","by":{"0":"54"}},{"t":"case","label":"National Ass’n of Home Builders v. Defenders of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"0":"55"}},{"t":"case","label":"Nishimura Ekiu v. United States","cite":"142 U.S. 651","y":1892,"id":"scdb/1891-092","sc":1,"sum":"The act of March 3, 1891, c. 551, forbidding certain classes of alien immigrants to land in the United States, is constitutional and valid.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Nixon v. Fitzgerald","cite":"457 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"sum":"The Court held that the President \"is entitled to absolute immunity from damages liability predicated on his official acts.\" This sweeping immunity, argued Justice Powell, was a function of the \"President's unique office, rooted in the constitutional tradition of separation of powers and supported by our history.\".","sumSrc":"Oyez","by":{"0":"72"}},{"t":"case","label":"Radzanower v. Touche Ross & Co.","cite":"426 U.S. 148","y":1976,"id":"1975/75-268","sc":1,"sum":"Venue in a suit against a national banking association charged with violating the Securities Exchange Act of 1934 held to be governed by the venue provision of the National Bank Act, 12 U. S. C. § 94, which provides that an action against a national banking association may be had in any federal district court within the district in which such association may be established, rather than by § 27 of the Securities …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"51, 56","1":"26"}},{"t":"case","label":"Raines v. Byrd","cite":"521 U.S. 811","y":1997,"id":"1996/96-1671","sc":1,"sum":"In a 7-to-2 decision, which avoided the question of the Act's constitutionality, the Court held that the individual congressmen lacked proper Article III standing to maintain their suit. The Court explained that the congressmen failed to show how the allegedly unconstitutional Act resulted in their personal injury, since it applied to the entire institution of Congress.","sumSrc":"Oyez","by":{"0":"34, 35"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Comm.","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"sum":"Announced by Justice Antonin Scalia, the Court ruled that the IIRIRA deprives federal courts of jurisdiction over the selective-enforcement claim.","sumSrc":"Oyez","by":{"0":"42, 44, 64, 72","1":"29, 32"}},{"t":"case","label":"Republican Party of Minn. v. White","cite":"536 U.S. 765","y":2002,"id":"2001/01-521","sc":1,"sum":"The Court held that the announce clause violates the First Amendment. The Court reasoned that the announce clause prohibits speech based on its content and burdens a category of speech that is at the core of First Amendment freedoms - speech about the qualifications of candidates for public office.","sumSrc":"Oyez","by":{"0":"74"}},{"t":"case","label":"Saavedra Bruno v. Albright","cite":"197 F.3d 1153","y":1999,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/197/1153/","by":{"0":"24, 25, 26","1":"2, 3, 4, 6, 8"}},{"t":"case","label":"Sale v. Haitian Ctrs. Council, Inc.","cite":"509 U.S. 155","y":1993,"id":"1992/92-344","sc":1,"sum":"And, it found that both section 243(h) and Article 33 are silent regarding extraterritorial application. In fact, the language of both suggests that only individuals who have already arrived on United States soil are protected, and their use throughout history confirms this interpretation. Thus, the judgment of the Court of Appeals is reversed.","sumSrc":"Oyez","by":{"0":"40, 53","1":"5, 24"}},{"t":"case","label":"Sanchez-Espinoza v. Reagan","cite":"770 F.2d 202","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/770/202/","by":{"0":"75"}},{"t":"case","label":"Shaughnessy v. United States ex rel. Mezei","cite":"345 U.S. 206","y":1953,"id":"scdb/1952-067","sc":1,"sum":"The Attorney General's continued exclusion of the alien without a hearing does not amount to an unlpvful detention, and courts may not temporarily admit him to the iJnited States pending arrangements for his departure abroad.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Smith v. Jefferson Cnty. Bd. of Sch. Comm’rs","cite":"641 F.3d 197","y":2011,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/641/197/","by":{"0":"29"}},{"t":"case","label":"Texas v. United States","cite":"809 F.3d 134","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/809/134/","by":{"0":"82"}},{"t":"case","label":"U.S. Bancorp Mortg. Co. v. Bonner Mall P’ship","cite":"513 U.S. 18","y":1994,"id":"1994/93-714","sc":1,"sum":"After this Court granted the petition for a writ of certiorari and received briefing on the merits, the parties entered into a settlement and agreed that the case was thereby mooted. Petitioner, however, also requested that the Court exercise its power under 28 U. S. C. § 2106 to vacate the judgment of the Court of Appeals. Respondent opposed the motion.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"United States v. Chemical Found., Inc.","cite":"272 U.S. 1","y":1926,"id":"scdb/1926-001","sc":1,"sum":"1. A decree of the Circuit Court of Appeals, entered prior to the taking effect of the Jurisdictional Act of February 13, 1925, and affirming dismissal on the merits of a bill by the United States to set aside, as unauthorized and fraudulently procured, sales of patent and other rights and properties seized pursuant to the Trading, with the Enemy Act, was reviewable by this Court on appeal (Jud. Code §§ 128, 241). …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"78"}},{"t":"case","label":"United States v. George S. Bush & Co.","cite":"310 U.S. 371","y":1940,"id":"scdb/1939-072","sc":1,"sum":"The President, acting on a report and recommendation of the Tariff Commission pursuant to the flexible tariff provisions of the Tariff Act of 1930, proclaimed an increase of duty on a Japanese product, to equalize the difference between Japanese and domestic costs of production. In fixing the increase, foreign cost of production was determined, under § 336 (e), on the \"weighted average of the invoice prices or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"United States v. Munsingwear, Inc.","cite":"340 U.S. 36","y":1950,"id":"scdb/1950-004","sc":1,"sum":"The dismissal is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30, 37"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"sum":"The Court held that the President does not have executive privilege in immunity from subpoenas or other civil court actions.","sumSrc":"Oyez","by":{"0":"72"}},{"t":"case","label":"United States v. Verdugo-Urquidez","cite":"494 U.S. 259","y":1990,"id":"1989/88-1353","sc":1,"sum":"The text of the Fourth Amendment concerns \"the people,\" suggesting a concern with persons who are part of the national community, as contrasted with aliens without any substantial connection to the U.S. Moreover, extraterritorial aliens are not even entitled to rights under the Fifth Amendment, which speaks in the relatively more universal term of \"person.\" And non-\"fundamental\" rights are not even guaranteed to inhabitants of unincorporated territories under U.S sovereign control, much less aliens.","sumSrc":"Oyez","by":{"0":"26, 35"}},{"t":"case","label":"United States ex rel. Knauff v. Shaughnessy","cite":"338 U.S. 537","y":1950,"id":"scdb/1949-033","sc":1,"sum":"This action was authorized by the Act of June 21, 1941, 22 U. S. C. § 223, and the proclamations and regulations issued thereunder, notwithstanding the War Brides Act of December 28, 1945, 8 U. S. C. § 232 et seq.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 4, 23, 24, 26, 40","1":"2, 7, 21"}},{"t":"case","label":"Valley Forge Christian Coll. v. Americans United for Separation of Church & State, Inc.","cite":"454 U.S. 464","y":1982,"id":"1981/80-327","sc":1,"sum":"The Court held that Americans United for Separation of Church and State did not have standing to sue. Justice Rehnquist argued that the group did not pass the first prong of the Court's test for taxpayer standing.","sumSrc":"Oyez","by":{"0":"31, 32","1":"12"}},{"t":"case","label":"Washington v. Trump: No. 17-141","cite":"2017 WL 462040","y":2017,"court":"W.D. Wash. Feb. 3","by":{"0":"6"}},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1987,"id":"1987/86-1294","sc":1,"sum":"Section 102(c) of the National Security Act of 1947 (NSA) authorizes the Director of the Central Intelligence Agency (CIA), \"in his discretion,\" to terminate the employment of any CIA employee \"whenever he shall deem such termination necessary or advisable in the interests of the United States.\" After respondent, a covert electronics technician in the CIA's employ, voluntarily informed the agency that he was a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 41, 42","1":"5, 7, 18"}},{"t":"case","label":"Western & S. Life Ins. Co. v. State Bd. of Equalization of Cal.","cite":"451 U.S. 648","y":1981,"id":"1980/79-1423","sc":1,"sum":"California, in addition to imposing a premiums tax on both foreign and domestic insurance companies doing business in the State, imposes a \"retaliatory\" tax on such a foreign insurer when the insurer's State of incorporation imposes higher taxes on California insurers doing business in that State than California would otherwise impose on that State's insurers doing business in California. Appellant, an Ohio insurer …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"64"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"0":"66"}},{"t":"case","label":"Zelman v. Simmons-Harris","cite":"536 U.S. 639","y":2002,"id":"2001/00-1751","sc":1,"sum":"The Court held that Ohio’s Pilot Project Scholarship Program did not violate the Establishment Clause while providing school tuition vouchers eligible for use at religiously-affiliated schools.","sumSrc":"Oyez","by":{"0":"33","1":"16"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"137 S. Ct. 1843","y":2017,"id":"2016/15-1358","sc":1,"sum":"The Court determined that, in suits against government officials for personally violating the Constitution, “context” should be defined narrowly for the purpose of determining whether a claim arose in a “new context,” and the government officials in this case are entitled to qualified immunity.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Kerry","cite":"135 S. Ct. 2076","y":2015,"id":"2014/13-628","sc":1,"sum":"The Court held that a federal statute directing the Secretary of State to record the birthplace of a citizen born in Jerusalem as “Israel” if requested to do so impermissibly infringed on the President’s power to recognize foreign states.","sumSrc":"Oyez","by":{"0":"65"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["criminal-jury-venue","Criminal Jury and Venue Clause"],["treason","Treason Clause"],["treason-punishment","Punishment of Treason Clause"]],"by":{"0":"22, 28, 78"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"15, 33"}},{"t":"usc","label":"8 U.S.C. § 1105a","url":"https://www.law.cornell.edu/uscode/text/8/1105a","subs":["(b)(1994)","(1994)"],"by":{"0":"25, 26"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)","(a)(1)","(a)(2)"],"stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"0":"25, 26","1":"2, 2, 2, 4"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","subs":["(1)"],"stext":{"head":"§702. Right of review","paras":[[0,"A person suffering legal wrong because of agency action, or adversely affected or aggrieved by agency action within the meaning of a relevant statute, is entitled to judicial review thereof. An action in a court of the United States seeking relief other than money damages and stating a claim that an agency or an officer or employee thereof acted or failed to act in an official capacity or under color of legal authority shall not be dismissed nor relief therein be denied on the ground that it is against the United States or that the United States is an indispensable party. The United States may be named as a defendant in any such action, and a judgment or decree may be entered against the United States: Provided, That any mandatory or injunctive decree shall specify the Federal officer or officers (by name or by title), and their successors in office, personally responsible for compliance. Nothing herein (1) affects other limitations on judicial review or the power or duty of the court to dismiss any action or deny relief on any other appropriate legal or equitable ground; or (2) confers authority to grant relief if any other statute that grants consent to suit expressly or impliedly forbids the relief which is sought."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/5/702?type=usc&year=mostrecent&link-type=html"},"head":"§702. Right of review","tname":"Government Organization and Employees","by":{"0":"26","1":"2, 4, 4"}},{"t":"law","label":"Pub. L. No. 95-426","url":"https://www.govinfo.gov/link/statute/92/992","by":{"0":"56","1":"24"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(42)","(a)(15)(E)","(a)(15)(E)(iii)","(a)(15)(F)(iii)","(a)(21)","(b)(1)(G)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"3, 6","1":"3, 28, 28, 28, 28, 28"}},{"t":"usc","label":"8 U.S.C. § 1152","url":"https://www.law.cornell.edu/uscode/text/8/1152","subs":["(a)","(a)(1)(A)","(a)(1)"],"stext":{"head":"§1152. Numerical limitations on individual foreign states","paras":[[0,"(a) Per country level"],[0,"(1) Nondiscrimination"],[1,"(A) Except as specifically provided in paragraph (2) and in sections 1101(a)(27), 1151(b)(2)(A)(i), and 1153 of this title, no person shall receive any preference or priority or be discriminated against in the issuance of an immigrant visa because of the person's race, sex, nationality, place of birth, or place of residence."],[1,"(B) Nothing in this paragraph shall be construed to limit the authority of the Secretary of State to determine the procedures for the processing of immigrant visa applications or the locations where such applications will be processed."],[0,"(2) Per country levels for family-sponsored and employment-based immigrants"],[1,"Subject to paragraphs (3), (4), and (5), the total number of immigrant visas made available to natives of any single foreign state or dependent area under subsections (a) and (b) of section 1153 of this title in any fiscal year may not exceed 7 percent (in the case of a single foreign state) or 2 percent (in the case of a dependent area) of the total number of such visas made available under such subsections in that fiscal year."],[0,"(3) Exception if additional visas available"],[1,"If because of the application of paragraph (2) with respect to one or more foreign states or dependent areas, the total number of visas available under both subsections (a) and (b) of section 1153 of this title for a calendar quarter exceeds the number of qualified immigrants who otherwise may be issued such a visa, paragraph (2) shall not apply to visas made available to such states or areas during the remainder of such calendar quarter."],[0,"(4) Special rules for spouses and children of lawful permanent resident aliens"],[0,"(A) 75 percent of 2nd preference set-aside for spouses and children not subject to per country limitation"],[0,"(i) In general"],[3,"Of the visa numbers made available under section 1153(a) of this title to immigrants described in section 1153(a)(2)(A) of this title in any fiscal year, 75 percent of the 2–A floor (as defined in clause (ii)) shall be issued without regard to the numerical limitation under paragraph (2)."],[0,"(ii) \"2–A floor\" defined"],[3,"In this paragraph, the term \"2–A floor\" means, for a fiscal year, 77 percent of the total number of visas made available under section 1153(a) of this title to immigrants described in section 1153(a)(2) of this title in the fiscal year."],[0,"(B) Treatment of remaining 25 percent for countries subject to subsection (e)"],[0,"(i) In general"],[3,"Of the visa numbers made available under section 1153(a) of this title to immigrants described in section 1153(a)(2)(A) of this title in any fiscal year, the remaining 25 percent of the 2–A floor shall be available in the case of a state or area that is subject to subsection (e) only to the extent that the total number of visas issued in accordance with subparagraph (A) to natives of the foreign state or area is less than the subsection (e) ceiling (as defined in clause (ii))."],[0,"(ii) \"Subsection (e) ceiling\" defined"],[3,"In clause (i), the term \"subsection (e) ceiling\" means, for a foreign state or dependent area, 77 percent of the maximum number of visas that may be made available under section 1153(a) of this title to immigrants who are natives of the state or area under section 1153(a)(2) of this title consistent with subsection (e)."],[0,"(C) Treatment of unmarried sons and daughters in countries subject to subsection (e)"],[2,"In the case of a foreign state or dependent area to which subsection (e) applies, the number of immigrant visas that may be made available to natives of the state or area under section 1153(a)(2)(B) of this title may not exceed—"],[3,"(i) 23 percent of the maximum number of visas that may be made available under section 1153(a) of this title to immigrants of the state or area described in section 1153(a)(2) of this title consistent with subsection (e), or"],[3,"(ii) the number (if any) by which the maximum number of visas that may be made available under section 1153(a) of this title to immigrants of the state or area described in section 1153(a)(2) of this title consistent with subsection (e) exceeds the number of visas issued under section 1153(a)(2)(A) of this title,"],[2,"whichever is greater."],[0,"(D) Limiting pass down for certain countries subject to subsection (e)"],[2,"In the case of a foreign state or dependent area to which subsection (e) applies, if the total number of visas issued under section 1153(a)(2) of this title exceeds the maximum number of visas that may be made available to immigrants of the state or area under section 1153(a)(2) of this title consistent with subsection (e) (determined without regard to this paragraph), in applying paragraphs (3) and (4) of section 1153(a) of this title under subsection (e)(2) all visas shall be deemed to have been required for the classes specified in paragraphs (1) and (2) of such section."],[0,"(5) Rules for employment-based immigrants"],[0,"(A) Employment-based immigrants not subject to per country limitation if additional visas available"],[2,"If the total number of visas available under paragraph (1), (2), (3), (4), or (5) of section 1153(b) of this title for a calendar quarter exceeds the number of qualified immigrants who may otherwise be issued such visas, the visas made available under that paragraph shall be issued without regard to the numerical limitation under paragraph (2) of this subsection during the remainder of the calendar quarter."],[0,"(B) Limiting fall across for certain countries subject to subsection (e)"],[2,"In the case of a foreign state or dependent area to which subsection (e) applies, if the total number of visas issued under section 1153(b) of this title exceeds the maximum number of visas that may be made available to immigrants of the state or area under section 1153(b) of this title consistent with subsection (e) (determined without regard to this paragraph), in applying subsection (e) all visas shall be deemed to have been required for the classes of aliens specified in section 1153(b) of this title."],[0,"(b) Rules for chargeability"],[0,"Each independent country, self-governing dominion, mandated territory, and territory under the international trusteeship system of the United Nations, other than the United States and its outlying possessions, shall be treated as a separate foreign state for the purposes of a numerical level established under subsection (a)(2) when approved by the Secretary of State. All other inhabited lands shall be attributed to a foreign state specified by the Secretary of State. For the purposes of this chapter the foreign state to which an immigrant is chargeable shall be determined by birth within such foreign state except that (1) an alien child, when accompanied by or following to join his alien parent or parents, may be charged to the foreign state of either parent if such parent has received or would be qualified for an immigrant visa, if necessary to prevent the separation of the child from the parent or parents, and if immigration charged to the foreign state to which such parent has been or would be chargeable has not reached a numerical level established under subsection (a)(2) for that fiscal year; (2) if an alien is chargeable to a different foreign state from that of his spouse, the foreign state to which such alien is chargeable may, if necessary to prevent the separation of husband and wife, be determined by the foreign state of the spouse he is accompanying or following to join, if such spouse has received or would be qualified for an immigrant visa and if immigration charged to the foreign state to which such spouse has been or would be chargeable has not reached a numerical level established under subsection (a)(2) for that fiscal year; (3) an alien born in the United States shall be considered as having been born in the country of which he is a citizen or subject, or, if he is not a citizen or subject of any country, in the last foreign country in which he had his residence as determined by the consular officer; and (4) an alien born within any foreign state in which neither of his parents was born and in which neither of his parents had a residence at the time of such alien's birth may be charged to the foreign state of either parent."],[0,"(c) Chargeability for dependent areas"],[0,"Any immigrant born in a colony or other component or dependent area of a foreign state overseas from the foreign state, other than an alien described in section 1151(b) of this title, shall be chargeable for the purpose of the limitation set forth in subsection (a), to the foreign state."],[0,"(d) Changes in territory"],[0,"In the case of any change in the territorial limits of foreign states, the Secretary of State shall, upon recognition of such change issue appropriate instructions to all diplomatic and consular offices."],[0,"(e) Special rules for countries at ceiling"],[0,"If it is determined that the total number of immigrant visas made available under subsections (a) and (b) of section 1153 of this title to natives of any single foreign state or dependent area will exceed the numerical limitation specified in subsection (a)(2) in any fiscal year, in determining the allotment of immigrant visa numbers to natives under subsections (a) and (b) of section 1153 of this title, visa numbers with respect to natives of that state or area shall be allocated (to the extent practicable and otherwise consistent with this section and section 1153 of this title) in a manner so that—"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1152?type=usc&year=mostrecent&link-type=html"},"head":"§1152. Numerical limitations on individual foreign states","tname":"Aliens and Nationality","by":{"0":"4, 4","1":"27, 8, 24, 25, 26, 27"}},{"t":"usc","label":"8 U.S.C. § 1157","url":"https://www.law.cornell.edu/uscode/text/8/1157","subs":["(a)","(a)(2)","(b)","(e)"],"stext":{"head":"§1157. Annual admission of refugees and admission of emergency situation refugees","paras":[[0,"(a) Maximum number of admissions; increases for humanitarian concerns; allocations"],[0,"(1) Except as provided in subsection (b), the number of refugees who may be admitted under this section in fiscal year 1980, 1981, or 1982, may not exceed fifty thousand unless the President determines, before the beginning of the fiscal year and after appropriate consultation (as defined in subsection (e)), that admission of a specific number of refugees in excess of such number is justified by humanitarian concerns or is otherwise in the national interest."],[0,"(2) Except as provided in subsection (b), the number of refugees who may be admitted under this section in any fiscal year after fiscal year 1982 shall be such number as the President determines, before the beginning of the fiscal year and after appropriate consultation, is justified by humanitarian concerns or is otherwise in the national interest."],[0,"(3) Admissions under this subsection shall be allocated among refugees of special humanitarian concern to the United States in accordance with a determination made by the President after appropriate consultation."],[0,"(4) In the determination made under this subsection for each fiscal year (beginning with fiscal year 1992), the President shall enumerate, with the respective number of refugees so determined, the number of aliens who were granted asylum in the previous year."],[0,"(b) Determinations by President respecting number of admissions for humanitarian concerns"],[0,"If the President determines, after appropriate consultation, that (1) an unforeseen emergency refugee situation exists, (2) the admission of certain refugees in response to the emergency refugee situation is justified by grave humanitarian concerns or is otherwise in the national interest, and (3) the admission to the United States of these refugees cannot be accomplished under subsection (a), the President may fix a number of refugees to be admitted to the United States during the succeeding period (not to exceed twelve months) in response to the emergency refugee situation and such admissions shall be allocated among refugees of special humanitarian concern to the United States in accordance with a determination made by the President after the appropriate consultation provided under this subsection."],[0,"(c) Admission by Attorney General of refugees; criteria; admission status of spouse or child; applicability of other statutory requirements; termination of refugee status of alien, spouse or child"],[0,"(1) Subject to the numerical limitations established pursuant to subsections (a) and (b), the Attorney General may, in the Attorney General's discretion and pursuant to such regulations as the Attorney General may prescribe, admit any refugee who is not firmly resettled in any foreign country, is determined to be of special humanitarian concern to the United States, and is admissible (except as otherwise provided under paragraph (3)) as an immigrant under this chapter."],[0,"(2)(A) A spouse or child (as defined in section 1101(b)(1)(A), (B), (C), (D), or (E) of this title) of any refugee who qualifies for admission under paragraph (1) shall, if not otherwise entitled to admission under paragraph (1) and if not a person described in the second sentence of section 1101(a)(42) of this title, be entitled to the same admission status as such refugee if accompanying, or following to join, such refugee and if the spouse or child is admissible (except as otherwise provided under paragraph (3)) as an immigrant under this chapter. Upon the spouse's or child's admission to the United States, such admission shall be charged against the numerical limitation established in accordance with the appropriate subsection under which the refugee's admission is charged."],[0,"(B) An unmarried alien who seeks to accompany, or follow to join, a parent granted admission as a refugee under this subsection, and who was under 21 years of age on the date on which such parent applied for refugee status under this section, shall continue to be classified as a child for purposes of this paragraph, if the alien attained 21 years of age after such application was filed but while it was pending."],[0,"(3) The provisions of paragraphs (4), (5), and (7)(A) of section 1182(a) of this title shall not be applicable to any alien seeking admission to the United States under this subsection, and the Attorney General may waive any other provision of such section (other than paragraph (2)(C) or subparagraph (A), (B), (C), or (E) of paragraph (3)) with respect to such an alien for humanitarian purposes, to assure family unity, or when it is otherwise in the public interest. Any such waiver by the Attorney General shall be in writing and shall be granted only on an individual basis following an investigation. The Attorney General shall provide for the annual reporting to Congress of the number of waivers granted under this paragraph in the previous fiscal year and a summary of the reasons for granting such waivers."],[0,"(4) The refugee status of any alien (and of the spouse or child of the alien) may be terminated by the Attorney General pursuant to such regulations as the Attorney General may prescribe if the Attorney General determines that the alien was not in fact a refugee within the meaning of section 1101(a)(42) of this title at the time of the alien's admission."],[0,"(d) Oversight reporting and consultation requirements"],[0,"(1) Before the start of each fiscal year the President shall report to the Committees on the Judiciary of the House of Representatives and of the Senate regarding the foreseeable number of refugees who will be in need of resettlement during the fiscal year and the anticipated allocation of refugee admissions during the fiscal year. The President shall provide for periodic discussions between designated representatives of the President and members of such committees regarding changes in the worldwide refugee situation, the progress of refugee admissions, and the possible need for adjustments in the allocation of admissions among refugees."],[0,"(2) As soon as possible after representatives of the President initiate appropriate consultation with respect to the number of refugee admissions under subsection (a) or with respect to the admission of refugees in response to an emergency refugee situation under subsection (b), the Committees on the Judiciary of the House of Representatives and of the Senate shall cause to have printed in the Congressional Record the substance of such consultation."],[0,"(3)(A) After the President initiates appropriate consultation prior to making a determination under subsection (a), a hearing to review the proposed determination shall be held unless public disclosure of the details of the proposal would jeopardize the lives or safety of individuals."],[0,"(B) After the President initiates appropriate consultation prior to making a determination, under subsection (b), that the number of refugee admissions should be increased because of an unforeseen emergency refugee situation, to the extent that time and the nature of the emergency refugee situation permit, a hearing to review the proposal to increase refugee admissions shall be held unless public disclosure of the details of the proposal would jeopardize the lives or safety of individuals."],[0,"(e) \"Appropriate consultation\" defined"],[0,"For purposes of this section, the term \"appropriate consultation\" means, with respect to the admission of refugees and allocation of refugee admissions, discussions in person by designated Cabinet-level representatives of the President with members of the Committees on the Judiciary of the Senate and of the House of Representatives to review the refugee situation or emergency refugee situation, to project the extent of possible participation of the United States therein, to discuss the reasons for believing that the proposed admission of refugees is justified by humanitarian concerns or grave humanitarian concerns or is otherwise in the national interest, and to provide such members with the following information:"],[1,"(1) A description of the nature of the refugee situation."],[1,"(2) A description of the number and allocation of the refugees to be admitted and an analysis of conditions within the countries from which they came."],[1,"(3) A description of the proposed plans for their movement and resettlement and the estimated cost of their movement and resettlement."],[1,"(4) An analysis of the anticipated social, economic, and demographic impact of their admission to the United States."],[1,"(5) A description of the extent to which other countries will admit and assist in the resettlement of such refugees."],[1,"(6) An analysis of the impact of the participation of the United States in the resettlement of such refugees on the foreign policy interests of the United States."],[1,"(7) Such additional information as may be appropriate or requested by such members."],[0,"To the extent possible, information described in this subsection shall be provided at least two weeks in advance of discussions in person by designated representatives of the President with such members."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1157?type=usc&year=mostrecent&link-type=html"},"head":"§1157. Annual admission of refugees and admission of emergency situation refugees","tname":"Aliens and Nationality","by":{"0":"4, 4, 4, 4, 4","1":"28, 28"}},{"t":"usc","label":"8 U.S.C. § 1181","url":"https://www.law.cornell.edu/uscode/text/8/1181","by":{"0":"4"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)","(a)(1)","(a)(2)","(a)(3)(B)","(a)(3)(C)","(a)(3)(E)(ii)","(a)(3)(E)(iii)","(a)(7)(A)(i)","(a)(7)(B)(i)(II)","(a)(7)(B)(iv)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"0":"4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4","1":"24, 25, 31, 28, passim, 20"}},{"t":"usc","label":"8 U.S.C. § 1185","url":"https://www.law.cornell.edu/uscode/text/8/1185","subs":["(a)","(a)(1)","(a)(1)(A)"],"stext":{"head":"§1185. Travel control of citizens and aliens","paras":[[0,"(a) Restrictions and prohibitions"],[0,"Unless otherwise ordered by the President, it shall be unlawful—"],[1,"(1) for any alien to depart from or enter or attempt to depart from or enter the United States except under such reasonable rules, regulations, and orders, and subject to such limitations and exceptions as the President may prescribe;"],[1,"(2) for any person to transport or attempt to transport from or into the United States another person with knowledge or reasonable cause to believe that the departure or entry of such other person is forbidden by this section;"],[1,"(3) for any person knowingly to make any false statement in an application for permission to depart from or enter the United States with intent to induce or secure the granting of such permission either for himself or for another;"],[1,"(4) for any person knowingly to furnish or attempt to furnish or assist in furnishing to another a permit or evidence of permission to depart or enter not issued and designed for such other person's use;"],[1,"(5) for any person knowingly to use or attempt to use any permit or evidence of permission to depart or enter not issued and designed for his use;"],[1,"(6) for any person to forge, counterfeit, mutilate, or alter, or cause or procure to be forged, counterfeited, mutilated, or altered, any permit or evidence of permission to depart from or enter the United States;"],[1,"(7) for any person knowingly to use or attempt to use or furnish to another for use any false, forged, counterfeited, mutilated, or altered permit, or evidence of permission, or any permit or evidence of permission which, though originally valid, has become or been made void or invalid."],[0,"(b) Citizens"],[0,"Except as otherwise provided by the President and subject to such limitations and exceptions as the President may authorize and prescribe, it shall be unlawful for any citizen of the United States to depart from or enter, or attempt to depart from or enter, the United States unless he bears a valid United States passport."],[0,"(c) Definitions"],[0,"The term \"United States\" as used in this section includes the Canal Zone, and all territory and waters, continental or insular, subject to the jurisdiction of the United States. The term \"person\" as used in this section shall be deemed to mean any individual, partnership, association, company, or other incorporated body of individuals, or corporation, or body politic."],[0,"(d) Nonadmission of certain aliens"],[0,"Nothing in this section shall be construed to entitle an alien to whom a permit to enter the United States has been issued to enter the United States, if, upon arrival in the United States, he is found to be inadmissible under any of the provisions of this chapter, or any other law, relative to the entry of aliens into the United States."],[0,"(e) Revocation of proclamation as affecting penalties"],[0,"The revocation of any rule, regulation, or order issued in pursuance of this section shall not prevent prosecution for any offense committed, or the imposition of any penalties or forfeitures, liability for which was incurred under this section prior to the revocation of such rule, regulation, or order."],[0,"(f) Permits to enter"],[0,"Passports, visas, reentry permits, and other documents required for entry under this chapter may be considered as permits to enter for the purposes of this section."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1185?type=usc&year=mostrecent&link-type=html"},"head":"§1185. Travel control of citizens and aliens","tname":"Aliens and Nationality","by":{"0":"4, 4","1":"22, 23, passim, 26"}},{"t":"usc","label":"8 U.S.C. § 1187","url":"https://www.law.cornell.edu/uscode/text/8/1187","subs":["(a)(12)(A)(i)","(a)(12)(A)(ii)","(a)(12)(D)(i)","(a)(12)(D)(ii)"],"stext":{"head":"§1187. Visa waiver program for certain visitors","paras":[[0,"(a) Establishment of program"],[0,"The Secretary of Homeland Security and the Secretary of State are authorized to establish a program (hereinafter in this section referred to as the \"program\") under which the requirement of paragraph (7)(B)(i)(II) of section 1182(a) of this title may be waived by the Secretary of Homeland Security, in consultation with the Secretary of State and in accordance with this section, in the case of an alien who meets the following requirements:"],[0,"(1) Seeking entry as tourist for 90 days or less"],[1,"The alien is applying for admission during the program as a nonimmigrant visitor (described in section 1101(a)(15)(B) of this title) for a period not exceeding 90 days."],[0,"(2) National of program country"],[1,"The alien is a national of, and presents a passport issued by, a country which—"],[2,"(A) extends (or agrees to extend), either on its own or in conjunction with one or more other countries that are described in subparagraph (B) and that have established with it a common area for immigration admissions, reciprocal privileges to citizens and nationals of the United States, and"],[2,"(B) is designated as a pilot program country under subsection (c)."],[0,"(3) Passport requirements"],[1,"The alien, at the time of application for admission, is in possession of a valid unexpired passport that satisfies the following:"],[0,"(A) Machine readable"],[2,"The passport is a machine-readable passport that is tamper-resistant, incorporates document authentication identifiers, and otherwise satisfies the internationally accepted standard for machine readability."],[0,"(B) Electronic"],[2,"Beginning on April 1, 2016, the passport is an electronic passport that is fraud-resistant, contains relevant biographic and biometric information (as determined by the Secretary of Homeland Security), and otherwise satisfies internationally accepted standards for electronic passports."],[0,"(4) Executes immigration forms"],[1,"The alien before the time of such admission completes such immigration form as the Secretary of Homeland Security shall establish."],[0,"(5) Entry into the United States"],[1,"If arriving by sea or air, the alien arrives at the port of entry into the United States on a carrier, including any carrier conducting operations under part 135 of title 14, Code of Federal Regulations, or a noncommercial aircraft that is owned or operated by a domestic corporation conducting operations under part 91 of title 14, Code of Federal Regulations 1 which has entered into an agreement with the Secretary of Homeland Security pursuant to subsection (e). The Secretary of Homeland Security is authorized to require a carrier conducting operations under part 135 of title 14, Code of Federal Regulations, or a domestic corporation conducting operations under part 91 of that title, to give suitable and proper bond, in such reasonable amount and containing such conditions as the Secretary of Homeland Security may deem sufficient to ensure compliance with the indemnification requirements of this section, as a term of such an agreement."],[0,"(6) Not a safety threat"],[1,"The alien has been determined not to represent a threat to the welfare, health, safety, or security of the United States."],[0,"(7) No previous violation"],[1,"If the alien previously was admitted without a visa under this section, the alien must not have failed to comply with the conditions of any previous admission as such a nonimmigrant."],[0,"(8) Round-trip ticket"],[1,"The alien is in possession of a round-trip transportation ticket (unless this requirement is waived by the Secretary of Homeland Security under regulations or the alien is arriving at the port of entry on an aircraft operated under part 135 of title 14, Code of Federal Regulations, or a noncommercial aircraft that is owned or operated by a domestic corporation conducting operations under part 91 of title 14, Code of Federal Regulations)."],[0,"(9) Automated system check"],[1,"The identity of the alien has been checked using an automated electronic database containing information about the inadmissibility of aliens to uncover any grounds on which the alien may be inadmissible to the United States, and no such ground has been found."],[0,"(10) Electronic transmission of identification information"],[1,"Operators of aircraft under part 135 of title 14, Code of Federal Regulations, or operators of noncommercial aircraft that are owned or operated by a domestic corporation conducting operations under part 91 of title 14, Code of Federal Regulations, carrying any alien passenger who will apply for admission under this section shall furnish such information as the Secretary of Homeland Security by regulation shall prescribe as necessary for the identification of any alien passenger being transported and for the enforcement of the immigration laws. Such information shall be electronically transmitted not less than one hour prior to arrival at the port of entry for purposes of checking for inadmissibility using the automated electronic database."],[0,"(11) Eligibility determination under the electronic system for travel authorization"],[1,"Beginning on the date on which the electronic system for travel authorization developed under subsection (h)(3) is fully operational, each alien traveling under the program shall, before applying for admission to the United States, electronically provide to the system biographical information and such other information as the Secretary of Homeland Security shall determine necessary to determine the eligibility of, and whether there exists a law enforcement or security risk in permitting, the alien to travel to the United States. Upon review of such biographical information, the Secretary of Homeland Security shall determine whether the alien is eligible to travel to the United States under the program."],[0,"(12) Not present in Iraq, Syria, or any other country or area of concern"],[0,"(A) In general"],[2,"Except as provided in subparagraphs (B) and (C)—"],[3,"(i) the alien has not been present, at any time on or after March 1, 2011—"],[4,"(I) in Iraq or Syria;"],[4,"(II) in a country that is designated by the Secretary of State under section 4605(j) 2 of title 50 (as continued in effect under the International Emergency Economic Powers Act (50 U.S.C. 1701 et seq.)), section 2780 of title 22, section 2371 of title 22, or any other provision of law, as a country, the government of which has repeatedly provided support of acts of international terrorism; or"],[4,"(III) in any other country or area of concern designated by the Secretary of Homeland Security under subparagraph (D); and"],[3,"(ii) regardless of whether the alien is a national of a program country, the alien is not a national of—"],[4,"(I) Iraq or Syria;"],[4,"(II) a country that is designated, at the time the alien applies for admission, by the Secretary of State under section 4605(j) 2 of title 50 (as continued in effect under the International Emergency Economic Powers Act (50 U.S.C. 1701 et seq.)), section 2780 of title 22, section 2371 of title 22, or any other provision of law, as a country, the government of which has repeatedly provided support of acts of international terrorism; or"],[4,"(III) any other country that is designated, at the time the alien applies for admission, by the Secretary of Homeland Security under subparagraph (D)."],[0,"(B) Certain military personnel and government employees"],[2,"Subparagraph (A)(i) shall not apply in the case of an alien if the Secretary of Homeland Security determines that the alien was present—"],[3,"(i) in order to perform military service in the armed forces of a program country; or"],[3,"(ii) in order to carry out official duties as a full time employee of the government of a program country."],[0,"(C) Waiver"],[2,"The Secretary of Homeland Security may waive the application of subparagraph (A) to an alien if the Secretary determines that such a waiver is in the law enforcement or national security interests of the United States."],[0,"(D) Countries or areas of concern"],[0,"(i) In general"],[3,"Not later than 60 days after December 18, 2015, the Secretary of Homeland Security, in consultation with the Secretary of State and the Director of National Intelligence, shall determine whether the requirement under subparagraph (A) shall apply to any other country or area."],[0,"(ii) Criteria"],[3,"In making a determination under clause (i), the Secretary shall consider—"],[4,"(I) whether the presence of an alien in the country or area increases the likelihood that the alien is a credible threat to the national security of the United States;"],[4,"(II) whether a foreign terrorist organization has a significant presence in the country or area; and"],[4,"(III) whether the country or area is a safe haven for terrorists."],[0,"(iii) Annual review"],[3,"The Secretary shall conduct a review, on an annual basis, of any determination made under clause (i)."],[0,"(E) Report"],[2,"Beginning not later than one year after December 18, 2015, and annually thereafter, the Secretary of Homeland Security shall submit to the Committee on Homeland Security, the Committee on Foreign Affairs, the Permanent Select Committee on Intelligence, and the Committee on the Judiciary of the House of Representatives, and the Committee on Homeland Security and Governmental Affairs, the Committee on Foreign Relations, the Select Committee on Intelligence, and the Committee on the Judiciary of the Senate a report on each instance in which the Secretary exercised the waiver authority under subparagraph (C) during the previous year."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1187?type=usc&year=mostrecent&link-type=html"},"head":"§1187. Visa waiver program for certain visitors","tname":"Aliens and Nationality","by":{"0":"4, 4, 4, 4, 4","1":"28"}},{"t":"usc","label":"8 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/8/1201","subs":["(a)(1)","(g)","(h)","(i)"],"stext":{"head":"§1201. Issuance of visas","paras":[[0,"(a) Immigrants; nonimmigrants"],[0,"(1) Under the conditions hereinafter prescribed and subject to the limitations prescribed in this chapter or regulations issued thereunder, a consular officer may issue"],[1,"(A) to an immigrant who has made proper application therefor, an immigrant visa which shall consist of the application provided for in section 1202 of this title, visaed by such consular officer, and shall specify the foreign state, if any, to which the immigrant is charged, the immigrant's particular status under such foreign state, the preference, immediate relative, or special immigrant classification to which the alien is charged, the date on which the validity of the visa shall expire, and such additional information as may be required; and"],[1,"(B) to a nonimmigrant who has made proper application therefor, a nonimmigrant visa, which shall specify the classification under section 1101(a)(15) of this title of the nonimmigrant, the period during which the nonimmigrant visa shall be valid, and such additional information as may be required."],[0,"(2) The Secretary of State shall provide to the Service an electronic version of the visa file of each alien who has been issued a visa to ensure that the data in that visa file is available to immigration inspectors at the United States ports of entry before the arrival of the alien at such a port of entry."],[0,"(b) Registration; photographs; waiver of requirement"],[0,"Each alien who applies for a visa shall be registered in connection with his application, and shall furnish copies of his photograph signed by him for such use as may be by regulations required. The requirements of this subsection may be waived in the discretion of the Secretary of State in the case of any alien who is within that class of nonimmigrants enumerated in sections 1101(a)(15)(A), and 1101(a)(15)(G) of this title, or in the case of any alien who is granted a diplomatic visa on a diplomatic passport or on the equivalent thereof."],[0,"(c) Period of validity; renewal or replacement"],[0,"(1) Immigrant visas"],[1,"An immigrant visa shall be valid for such period, not exceeding six months, as shall be by regulations prescribed, except that any visa issued to a child lawfully adopted by a United States citizen and spouse while such citizen is serving abroad in the United States Armed Forces, or is employed abroad by the United States Government, or is temporarily abroad on business, shall be valid until such time, for a period not to exceed three years, as the adoptive citizen parent returns to the United States in due course of his service, employment, or business."],[0,"(2) Nonimmigrant visas"],[1,"A nonimmigrant visa shall be valid for such periods as shall be by regulations prescribed. In prescribing the period of validity of a nonimmigrant visa in the case of nationals of any foreign country who are eligible for such visas, the Secretary of State shall, insofar as practicable, accord to such nationals the same treatment upon a reciprocal basis as such foreign country accords to nationals of the United States who are within a similar class; except that in the case of aliens who are nationals of a foreign country and who either are granted refugee status and firmly resettled in another foreign country or are granted permanent residence and residing in another foreign country, the Secretary of State may prescribe the period of validity of such a visa based upon the treatment granted by that other foreign country to alien refugees and permanent residents, respectively, in the United States."],[0,"(3) Visa replacement"],[1,"An immigrant visa may be replaced under the original number during the fiscal year in which the original visa was issued for an immigrant who establishes to the satisfaction of the consular officer that the immigrant—"],[2,"(A) was unable to use the original immigrant visa during the period of its validity because of reasons beyond his control and for which he was not responsible;"],[2,"(B) is found by a consular officer to be eligible for an immigrant visa; and"],[2,"(C) pays again the statutory fees for an application and an immigrant visa."],[0,"(4) Fee waiver"],[1,"If an immigrant visa was issued, on or after March 27, 2013, for a child who has been lawfully adopted, or who is coming to the United States to be adopted, by a United States citizen, any statutory immigrant visa fees relating to a renewal or replacement of such visa may be waived or, if already paid, may be refunded upon request, subject to such criteria as the Secretary of State may prescribe, if—"],[2,"(A) the immigrant child was unable to use the original immigrant visa during the period of its validity as a direct result of extraordinary circumstances, including the denial of an exit permit; and"],[2,"(B) if such inability was attributable to factors beyond the control of the adopting parent or parents and of the immigrant."],[0,"(d) Physical examination"],[0,"Prior to the issuance of an immigrant visa to any alien, the consular officer shall require such alien to submit to a physical and mental examination in accordance with such regulations as may be prescribed. Prior to the issuance of a nonimmigrant visa to any alien, the consular officer may require such alien to submit to a physical or mental examination, or both, if in his opinion such examination is necessary to ascertain whether such alien is eligible to receive a visa."],[0,"(e) Surrender of visa"],[0,"Each immigrant shall surrender his immigrant visa to the immigration officer at the port of entry, who shall endorse on the visa the date and the port of arrival, the identity of the vessel or other means of transportation by which the immigrant arrived, and such other endorsements as may be by regulations required."],[0,"(f) Surrender of documents"],[0,"Each nonimmigrant shall present or surrender to the immigration officer at the port of entry such documents as may be by regulation required. In the case of an alien crewman not in possession of any individual documents other than a passport and until such time as it becomes practicable to issue individual documents, such alien crewman may be admitted, subject to the provisions of this part, if his name appears in the crew list of the vessel or aircraft on which he arrives and the crew list is visaed by a consular officer, but the consular officer shall have the right to deny admission to any alien crewman from the crew list visa."],[0,"(g) Nonissuance of visas or other documents"],[0,"No visa or other documentation shall be issued to an alien if (1) it appears to the consular officer, from statements in the application, or in the papers submitted therewith, that such alien is ineligible to receive a visa or such other documentation under section 1182 of this title, or any other provision of law, (2) the application fails to comply with the provisions of this chapter, or the regulations issued thereunder, or (3) the consular officer knows or has reason to believe that such alien is ineligible to receive a visa or such other documentation under section 1182 of this title, or any other provision of law: Provided, That a visa or other documentation may be issued to an alien who is within the purview of section 1182(a)(4) of this title, if such alien is otherwise entitled to receive a visa or other documentation, upon receipt of notice by the consular officer from the Attorney General of the giving of a bond or undertaking providing indemnity as in the case of aliens admitted under section 1183 of this title: Provided further, That a visa may be issued to an alien defined in section 1101(a)(15)(B) or (F) of this title, if such alien is otherwise entitled to receive a visa, upon receipt of a notice by the consular officer from the Attorney General of the giving of a bond with sufficient surety in such sum and containing such conditions as the consular officer shall prescribe, to insure that at the expiration of the time for which such alien has been admitted by the Attorney General, as provided in section 1184(a) of this title, or upon failure to maintain the status under which he was admitted, or to maintain any status subsequently acquired under section 1258 of this title, such alien will depart from the United States."],[0,"(h) Nonadmission upon arrival"],[0,"Nothing in this chapter shall be construed to entitle any alien, to whom a visa or other documentation has been issued, to be admitted 1 the United States, if, upon arrival at a port of entry in the United States, he is found to be inadmissible under this chapter, or any other provision of law. The substance of this subsection shall appear upon every visa application."],[0,"(i) Revocation of visas or documents"],[0,"After the issuance of a visa or other documentation to any alien, the consular officer or the Secretary of State may at any time, in his discretion, revoke such visa or other documentation. Notice of such revocation shall be communicated to the Attorney General, and such revocation shall invalidate the visa or other documentation from the date of issuance: Provided, That carriers or transportation companies, and masters, commanding officers, agents, owners, charterers, or consignees, shall not be penalized under section 1323(b) of this title for action taken in reliance on such visas or other documentation, unless they received due notice of such revocation prior to the alien's embarkation. There shall be no means of judicial review (including review pursuant to section 2241 of title 28 or any other habeas corpus provision, and sections 1361 and 1651 of such title) of a revocation under this subsection, except in the context of a removal proceeding if such revocation provides the sole ground for removal under section 1227(a)(1)(B) of this title."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1201?type=usc&year=mostrecent&link-type=html"},"head":"§1201. Issuance of visas","tname":"Aliens and Nationality","by":{"0":"4, 4, 4, 4","1":"24, 27, 4"}},{"t":"usc","label":"8 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/8/1202","subs":["(h)"],"by":{"0":"4"}},{"t":"usc","label":"8 U.S.C. § 1203","url":"https://www.law.cornell.edu/uscode/text/8/1203","by":{"0":"4"}},{"t":"usc","label":"8 U.S.C. § 1204","url":"https://www.law.cornell.edu/uscode/text/8/1204","by":{"0":"4"}},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(a)"],"stext":{"head":"§1225. Inspection by immigration officers; expedited removal of inadmissible arriving aliens; referral for hearing","paras":[[0,"(a) Inspection"],[0,"(1) Aliens treated as applicants for admission"],[1,"An alien present in the United States who has not been admitted or who arrives in the United States (whether or not at a designated port of arrival and including an alien who is brought to the United States after having been interdicted in international or United States waters) shall be deemed for purposes of this chapter an applicant for admission."],[0,"(2) Stowaways"],[1,"An arriving alien who is a stowaway is not eligible to apply for admission or to be admitted and shall be ordered removed upon inspection by an immigration officer. Upon such inspection if the alien indicates an intention to apply for asylum under section 1158 of this title or a fear of persecution, the officer shall refer the alien for an interview under subsection (b)(1)(B). A stowaway may apply for asylum only if the stowaway is found to have a credible fear of persecution under subsection (b)(1)(B). In no case may a stowaway be considered an applicant for admission or eligible for a hearing under section 1229a of this title."],[0,"(3) Inspection"],[1,"All aliens (including alien crewmen) who are applicants for admission or otherwise seeking admission or readmission to or transit through the United States shall be inspected by immigration officers."],[0,"(4) Withdrawal of application for admission"],[1,"An alien applying for admission may, in the discretion of the Attorney General and at any time, be permitted to withdraw the application for admission and depart immediately from the United States."],[0,"(5) Statements"],[1,"An applicant for admission may be required to state under oath any information sought by an immigration officer regarding the purposes and intentions of the applicant in seeking admission to the United States, including the applicant's intended length of stay and whether the applicant intends to remain permanently or become a United States citizen, and whether the applicant is inadmissible."],[0,"(b) Inspection of applicants for admission"],[0,"(1) Inspection of aliens arriving in the United States and certain other aliens who have not been admitted or paroled"],[0,"(A) Screening"],[0,"(i) In general"],[3,"If an immigration officer determines that an alien (other than an alien described in subparagraph (F)) who is arriving in the United States or is described in clause (iii) is inadmissible under section 1182(a)(6)(C) or 1182(a)(7) of this title, the officer shall order the alien removed from the United States without further hearing or review unless the alien indicates either an intention to apply for asylum under section 1158 of this title or a fear of persecution."],[0,"(ii) Claims for asylum"],[3,"If an immigration officer determines that an alien (other than an alien described in subparagraph (F)) who is arriving in the United States or is described in clause (iii) is inadmissible under section 1182(a)(6)(C) or 1182(a)(7) of this title and the alien indicates either an intention to apply for asylum under section 1158 of this title or a fear of persecution, the officer shall refer the alien for an interview by an asylum officer under subparagraph (B)."],[0,"(iii) Application to certain other aliens"],[0,"(I) In general"],[4,"The Attorney General may apply clauses (i) and (ii) of this subparagraph to any or all aliens described in subclause (II) as designated by the Attorney General. Such designation shall be in the sole and unreviewable discretion of the Attorney General and may be modified at any time."],[0,"(II) Aliens described"],[4,"An alien described in this clause is an alien who is not described in subparagraph (F), who has not been admitted or paroled into the United States, and who has not affirmatively shown, to the satisfaction of an immigration officer, that the alien has been physically present in the United States continuously for the 2-year period immediately prior to the date of the determination of inadmissibility under this subparagraph."],[0,"(B) Asylum interviews"],[0,"(i) Conduct by asylum officers"],[3,"An asylum officer shall conduct interviews of aliens referred under subparagraph (A)(ii), either at a port of entry or at such other place designated by the Attorney General."],[0,"(ii) Referral of certain aliens"],[3,"If the officer determines at the time of the interview that an alien has a credible fear of persecution (within the meaning of clause (v)), the alien shall be detained for further consideration of the application for asylum."],[0,"(iii) Removal without further review if no credible fear of persecution"],[0,"(I) In general"],[4,"Subject to subclause (III), if the officer determines that an alien does not have a credible fear of persecution, the officer shall order the alien removed from the United States without further hearing or review."],[0,"(II) Record of determination"],[4,"The officer shall prepare a written record of a determination under subclause (I). Such record shall include a summary of the material facts as stated by the applicant, such additional facts (if any) relied upon by the officer, and the officer's analysis of why, in the light of such facts, the alien has not established a credible fear of persecution. A copy of the officer's interview notes shall be attached to the written summary."],[0,"(III) Review of determination"],[4,"The Attorney General shall provide by regulation and upon the alien's request for prompt review by an immigration judge of a determination under subclause (I) that the alien does not have a credible fear of persecution. Such review shall include an opportunity for the alien to be heard and questioned by the immigration judge, either in person or by telephonic or video connection. Review shall be concluded as expeditiously as possible, to the maximum extent practicable within 24 hours, but in no case later than 7 days after the date of the determination under subclause (I)."],[0,"(IV) Mandatory detention"],[4,"Any alien subject to the procedures under this clause shall be detained pending a final determination of credible fear of persecution and, if found not to have such a fear, until removed."],[0,"(iv) Information about interviews"],[3,"The Attorney General shall provide information concerning the asylum interview described in this subparagraph to aliens who may be eligible. An alien who is eligible for such interview may consult with a person or persons of the alien's choosing prior to the interview or any review thereof, according to regulations prescribed by the Attorney General. Such consultation shall be at no expense to the Government and shall not unreasonably delay the process."],[0,"(v) \"Credible fear of persecution\" defined"],[3,"For purposes of this subparagraph, the term \"credible fear of persecution\" means that there is a significant possibility, taking into account the credibility of the statements made by the alien in support of the alien's claim and such other facts as are known to the officer, that the alien could establish eligibility for asylum under section 1158 of this title."],[0,"(C) Limitation on administrative review"],[2,"Except as provided in subparagraph (B)(iii)(III), a removal order entered in accordance with subparagraph (A)(i) or (B)(iii)(I) is not subject to administrative appeal, except that the Attorney General shall provide by regulation for prompt review of such an order under subparagraph (A)(i) against an alien who claims under oath, or as permitted under penalty of perjury under section 1746 of title 28, after having been warned of the penalties for falsely making such claim under such conditions, to have been lawfully admitted for permanent residence, to have been admitted as a refugee under section 1157 of this title, or to have been granted asylum under section 1158 of this title."],[0,"(D) Limit on collateral attacks"],[2,"In any action brought against an alien under section 1325(a) of this title or section 1326 of this title, the court shall not have jurisdiction to hear any claim attacking the validity of an order of removal entered under subparagraph (A)(i) or (B)(iii)."],[0,"(E) \"Asylum officer\" defined"],[2,"As used in this paragraph, the term \"asylum officer\" means an immigration officer who—"],[3,"(i) has had professional training in country conditions, asylum law, and interview techniques comparable to that provided to full-time adjudicators of applications under section 1158 of this title, and"],[3,"(ii) is supervised by an officer who meets the condition described in clause (i) and has had substantial experience adjudicating asylum applications."],[0,"(F) Exception"],[2,"Subparagraph (A) shall not apply to an alien who is a native or citizen of a country in the Western Hemisphere with whose government the United States does not have full diplomatic relations and who arrives by aircraft at a port of entry."],[0,"(G) Commonwealth of the Northern Mariana Islands"],[2,"Nothing in this subsection shall be construed to authorize or require any person described in section 1158(e) of this title to be permitted to apply for asylum under section 1158 of this title at any time before January 1, 2014."],[0,"(2) Inspection of other aliens"],[0,"(A) In general"],[2,"Subject to subparagraphs (B) and (C), in the case of an alien who is an applicant for admission, if the examining immigration officer determines that an alien seeking admission is not clearly and beyond a doubt entitled to be admitted, the alien shall be detained for a proceeding under section 1229a of this title."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1225?type=usc&year=mostrecent&link-type=html"},"head":"§1225. Inspection by immigration officers; expedited removal of inadmissible arriving aliens; referral for hearing","tname":"Aliens and Nationality","by":{"0":"4","1":"27"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","by":{"0":"26"}},{"t":"usc","label":"6 U.S.C. § 236","url":"https://www.law.cornell.edu/uscode/text/6/236","subs":["(b)(1)","(c)(1)"],"by":{"0":"53, 53, 53"}},{"t":"reg","label":"44 Fed. Reg. 67,947","url":"https://www.govinfo.gov/link/fr/44/67947","by":{"0":"53","1":"25"}},{"t":"reg","label":"Exec. Order No. 12,206, 45 Fed. Reg. 24,101","url":"https://www.govinfo.gov/link/fr/45/24101","by":{"0":"54","1":"25"}},{"t":"reg","label":"Exec. Order No. 12,807, 57 Fed. Reg. 23,133","url":"https://www.govinfo.gov/link/fr/57/23133","by":{"0":"43"}},{"t":"reg","label":"Exec. Order No. 13,606, 77 Fed. Reg. 24,571","url":"https://www.govinfo.gov/link/fr/77/24571","by":{"0":"59"}},{"t":"reg","label":"Exec. Order No. 13,692, 80 Fed. Reg. 12,747","url":"https://www.govinfo.gov/link/fr/80/12747","by":{"0":"59"}},{"t":"reg","label":"Exec. Order No. 13,694, 80 Fed. Reg. 18,077","url":"https://www.govinfo.gov/link/fr/80/18077","by":{"0":"59"}},{"t":"reg","label":"Exec. Order No. 13,769, 82 Fed. Reg. 8977","url":"https://www.govinfo.gov/link/fr/82/8977","by":{"0":"6"}},{"t":"reg","label":"Exec. Order No. 13,780, 82 Fed. Reg. 13,209","url":"https://www.govinfo.gov/link/fr/82/13209","by":{"0":"passim","1":"passim"}},{"t":"reg","label":"Proclamation No. 5517, 51 Fed. Reg. 30,470","url":"https://www.govinfo.gov/link/fr/51/30470","by":{"0":"43, 53","1":"21"}},{"t":"reg","label":"Proclamation No. 5829, 53 Fed. Reg. 22,289","url":"https://www.govinfo.gov/link/fr/53/22289","by":{"0":"43"}},{"t":"reg","label":"Proclamation No. 5887, 53 Fed. Reg. 43,185","url":"https://www.govinfo.gov/link/fr/53/43185","by":{"0":"43, 53"}},{"t":"reg","label":"Proclamation No. 6958, 61 Fed. Reg. 60,007","url":"https://www.govinfo.gov/link/fr/61/60007","by":{"0":"43, 53"}},{"t":"reg","label":"Proclamation No. 7750, 69 Fed. Reg. 2287","url":"https://www.govinfo.gov/link/fr/69/2287","by":{"0":"59"}},{"t":"reg","label":"Proclamation No. 8015, 71 Fed. Reg. 28,541","url":"https://www.govinfo.gov/link/fr/71/28541","by":{"0":"59"}},{"t":"reg","label":"Proclamation No. 8342, 74 Fed. Reg. 4093","url":"https://www.govinfo.gov/link/fr/74/4093","by":{"0":"43"}},{"t":"reg","label":"Proclamation No. 8693, 76 Fed. Reg. 44,751","url":"https://www.govinfo.gov/link/fr/76/44751","by":{"0":"43"}},{"t":"reg","label":"Proclamation No. 8697, 76 Fed. Reg. 49,277","url":"https://www.govinfo.gov/link/fr/76/49277","by":{"0":"59"}},{"t":"reg","label":"82 Fed. Reg. 27,965","url":"https://www.govinfo.gov/link/fr/82/27965","by":{"0":"37"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"135 S. Ct. 1378","y":2015,"id":"2014/14-15","sc":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"1":"9"}},{"t":"case","label":"Clark v. Rameker","cite":"134 S. Ct. 2242","y":2014,"id":"2013/13-299","sc":1,"sum":"The Court held that the U.S. Bankruptcy Code does not exempt inherited retirement accounts from a debtor's estate in bankruptcy proceedings.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Crosby v. National Foreign Trade Council","cite":"530 U.S. 363","y":2000,"id":"1999/99-474","sc":1,"sum":"The Court held that \"the state Act is preempted, and its application unconstitutional, under the Supremacy Clause.\" Justice Souter wrote for the Court that Massachusetts' law created an obstacle to the President's discretion to control economic sanctions against Burma, interfered with Congress's intention to limit economic pressure against the Burmese Government, and was at odds with the President's authority to speak for the United States among the world's nations to develop a comprehensive, multilateral Burma strategy.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Dames & Moore v. Regan","cite":"453 U.S. 654","y":1981,"id":"1980/80-2078","sc":1,"sum":"The Court held that the International Emergency Economic Powers Act constituted a specific congressional authorization for the President to order the transfer of Iranian assets. The Court further held that although the IEEPA itself did not authorize the presidential suspension of legal claims, previous acts of Congress had \"implicitly approved\" of executive control of claim settlement.","sumSrc":"Oyez","by":{"1":"6"}},{"t":"case","label":"Epperson v. Arkansas","cite":"393 U.S. 97","y":1968,"id":"1968/7","sc":1,"sum":"The Court found that a statute forbidding the teaching of human evolution violated the Establishment Clause of the First Amendment.","sumSrc":"Oyez","by":{"1":"12, 35"}},{"t":"case","label":"Estate of Thornton v. Caldor, Inc.","cite":"472 U.S. 703","y":1985,"id":"1984/83-1158","sc":1,"sum":"The Court held 8-to-1 that the Connecticut Sabbath observance statute was void, saying its \"unyielding weighing in favor of Sabbath observers over all other interests\" results in an unconstitutional mingling of church and state.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Glassroth v. Moore","cite":"335 F.3d 1282","y":2003,"url":"https://www.courtlistener.com/c/F.3d/335/1282/","by":{"1":"35"}},{"t":"case","label":"Grupo Mexicano de Desarollo S.A. v. Alliance Bond Fund, Inc.","cite":"527 U.S. 308","y":1999,"id":"1998/98-231","sc":1,"sum":"The Court held that the District Court lacked the authority to issue a preliminary injunction preventing defendants being sued by creditors from disposing of their assets pending adjudication of the creditor's contract claim for monetary damages because such a remedy was historically unavailable from a court of equity.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Hunter v. Underwood","cite":"417 U.S. 222","y":1985,"id":"1984/84-76","sc":1,"sum":"Section 182 violates the Equal Protection Clause of the Fourteenth Amendment. Arlington Heights v. MetropolitanHousingDevelopment Corp., 429 U. S. 252. That § 182 may have been adopted to discriminate against poor whites as well as against blacks would not render nugatory the purpose to discriminate against blacks, it being clear that the latter was a \"but-for\" motivation for adopting § 182. There is no evidence …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"Jimenez v. Quarterman","cite":"555 U.S. 113","y":2009,"id":"2008/07-6984","sc":1,"sum":"The Court held that if a state court grants a criminal defendant the right to file an out-of-time direct appeal, the statute of limitations doesn't begin until after the out-of-time appeal is final.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Kent v. Dulles","cite":"357 U.S. 116","y":1958,"id":"1957/481","sc":1,"sum":"In a 5-to-4 decision, the Court held that the right to travel is an inherent element of \"liberty\" that cannot be denied to American citizens.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Larkin v. Grendel’s Den, Inc.","cite":"459 U.S. 116","y":1982,"id":"1982/81-878","sc":1,"sum":"Section 16C violates the Establishment Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12"}},{"t":"case","label":"LeBlanc-Sternberg v. Fletcher","cite":"67 F.3d 412","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/67/412/","by":{"1":"35"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Pearson v. Callahan","cite":"555 U.S. 223","y":2009,"id":"2008/07-751","sc":1,"sum":"A case in which the Court overturned its previous decision in Saucier v. Katz, which prescribed a rigid test for government qualified immunity claims, and held that inquiries should be at the discretion of the lower courts.","sumSrc":"Oyez","by":{"1":"7"}},{"t":"case","label":"Pittston Coal Grp. v. Sebben","cite":"488 U.S. 105","y":1988,"id":"1988/87-821","sc":1,"sum":"The Black Lung Benefits Reform Act of 1977 (BLBRA), in 30 U. S. C. § 902(f)(2), provided that, pending the issuance of permanent regulations by the Secretary of Labor, cases filed or pending, as well as certain claims required to be reopened or readjudicated, were to be assessed under \"[c]riteria... not... more restrictive than the criteria applicable to a claim filed on June 30, 1973.\" As of that date, under …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Rajah v. Mukasey","cite":"544 F.3d 427","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/544/427/","by":{"1":"28"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Sekhar v. United States","cite":"133 S. Ct. 2720","y":2013,"id":"2012/12-357","sc":1,"sum":"The Court held that attempting to compel a person to issue a recommendation does not constitute extortion under the Hobbs Act.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Sessions v. Morales-Santana","cite":"137 S. Ct. 1678","y":2017,"id":"2016/15-1191","sc":1,"sum":"The Court held that statutory distinction between the physical presence requirements for transferral of derivative citizenship for unwed citizen mothers and unwed citizen fathers of foreign-born children violates the Equal Protection Clause of the Fifth Amendment, and it is up to Congress, rather than the courts, to create a uniform solution that does not disadvantage any person on the basis of gender.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"1":"5"}},{"t":"case","label":"Stern v. Marshall","cite":"564 U.S. 462","y":2011,"id":"2010/10-179","sc":1,"sum":"The Court held that the Bankruptcy Court did not have the constitutional authority to enter judgement on the petitioner's counterclaim.","sumSrc":"Oyez","by":{"1":"7"}},{"t":"case","label":"Summers v. Earth Island Inst.","cite":"555 U.S. 488","y":2009,"id":"2008/07-463","sc":1,"sum":"The Court held that the defendants did not have standing to challenge regulations of the U.S. Forest Service in the absence of a live dispute over the application of those regulations.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Thompson v. North Am. Stainless, LP","cite":"562 U.S. 170","y":2011,"id":"2010/09-291","sc":1,"sum":"The Court held that an employer violates Title VII of the Civil Rights Acts by firing the fiancee of an employee who complains about workplace discrimination.","sumSrc":"Oyez","by":{"1":"8"}},{"t":"case","label":"Two Guys From Harrison-Allentown, Inc. v. McGinley","cite":"179 F. Supp. 944","y":1959,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./179/944/","by":{"1":"11"}},{"t":"case","label":"United States v. Curtiss-Wright Exp. Corp.","cite":"299 U.S. 304","y":1936,"id":"1900-1940/299us304","sc":1,"sum":"The Court held that the President has greater legislative power in international affairs than would be allowed in domestic ones.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"United States v. Texas","cite":"136 S. Ct. 2271","y":2016,"id":"2015/15-674","sc":1,"sum":"A case in which the equally divided Court affirmed the lower court's judgment that the Deferred Action for Parents of Americans and Lawful Permanent Residents (DAPA) program was arbitrary and capricious, and failed to undergo notice-and-comment procedures as required by the Administrative Procedure Act.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"United States R.R. Ret. Bd. v. Fritz","cite":"449 U.S. 166","y":1980,"id":"1980/79-870","sc":1,"sum":"The Court held that laws may create classifications that are not elegant or “artfully drawn” but that are not unconstitutional. The Constitution would allow Congress to deny windfall benefits to all employees, therefore it was not unconstitutional to deny them to some.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Village of Arlington Heights v. Metropolitan Housing Dev. Corp.","cite":"429 U.S. 252","y":1977,"id":"1976/75-616","sc":1,"sum":"After finding that MHDC had proper federal standing, since it acted on behalf of black plaintiffs who stood to suffer direct and measurable injuries from Arlington's denial, the Court held that it failed to establish Arlington's racially discriminatory intent or purpose.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Washington v. Seattle Sch. Dist. No. 1","cite":"458 U.S. 457","y":1982,"id":"1981/81-9","sc":1,"sum":"The initiative reordered the educational decisionmaking process by moving the power over busing for purposes of integration to state control. The state explicitly employed \"the racial nature of a decision to determine the decisionmaking process.\" This kind of state action places an unconstitutional burden on racial minorities within the governmental process.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Washington v. Trump","cite":"858 F.3d 1168","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/858/1168/","by":{"1":"31"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["reduction-representation","Reduction of Representation Clause (Fourteenth Amendment, Section 2)"],["disqualification","Disqualification Clause (Section 3)"],["public-debt-clause","Public Debt Clause"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"1":"16"}},{"t":"usc","label":"5 U.S.C. § 703","url":"https://www.law.cornell.edu/uscode/text/5/703","by":{"1":"9"}},{"t":"usc","label":"8 U.S.C. § 1184","url":"https://www.law.cornell.edu/uscode/text/8/1184","subs":["(e)"],"by":{"1":"28"}},{"t":"usc","label":"8 U.S.C. § 1232","url":"https://www.law.cornell.edu/uscode/text/8/1232","by":{"1":"28"}},{"t":"usc","label":"8 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/8/1253","subs":["(d)"],"by":{"1":"27"}},{"t":"usc","label":"8 U.S.C. § 1254a","url":"https://www.law.cornell.edu/uscode/text/8/1254a","by":{"1":"28"}},{"t":"usc","label":"8 U.S.C. § 1255","url":"https://www.law.cornell.edu/uscode/text/8/1255","by":{"1":"28"}},{"t":"usc","label":"8 U.S.C. § 1329","url":"https://www.law.cornell.edu/uscode/text/8/1329","by":{"1":"6"}},{"t":"usc","label":"8 U.S.C. § 1437","url":"https://www.law.cornell.edu/uscode/text/8/1437","by":{"1":"28"}},{"t":"usc","label":"8 U.S.C. § 1735","url":"https://www.law.cornell.edu/uscode/text/8/1735","by":{"1":"28"}},{"t":"law","label":"Nicaraguan Adjustment and Central American Relief Act, Pub. L. No. 105-100","url":"https://www.govinfo.gov/link/plaw/105/public/100","by":{"1":"28"}},{"t":"reg","label":"Exec. Order No. 13,662, 79 Fed. Reg. 16,169","url":"https://www.govinfo.gov/link/fr/79/16169","by":{"1":"22"}},{"t":"reg","label":"45 Fed. Reg. 24,436","url":"https://www.govinfo.gov/link/fr/45/24436","by":{"1":"25"}},{"t":"reg","label":"Proclamation No. 6730, 59 Fed. Reg. 50,683","url":"https://www.govinfo.gov/link/fr/59/50683","by":{"1":"22"}},{"t":"reg","label":"Proclamation No. 7524, 67 Fed. Reg. 8857","url":"https://www.govinfo.gov/link/fr/67/8857","by":{"1":"22"}},{"t":"reg","label":"Proclamation No. 9645, 82 Fed. Reg. 45,161","url":"https://www.govinfo.gov/link/fr/82/45161","by":{"1":"1"}}]};